    <script>document.addEventListener('DOMContentLoaded',()=>{const role=document.querySelector('[data-role]'),extra=document.querySelector('[data-extra-role]'),sf=document.getElementById('salesforce-wrapper'),sfi=document.getElementById('salesforce_user_id'),it=document.getElementById('it-wrapper'),its=[...document.querySelectorAll('[data-it]')];const update=()=>{const sales=(role?role.value==='{{ \App\Models\User::ROLE_USER }}':true)&&{{ Js::from($rankedRoles) }}.includes(extra.value);const isIt=extra.value==='{{ \App\Models\User::ROLE_INFORMATION_TECHNOLOGY }}';sf.classList.toggle('hidden',!sales);sfi.required=sales;it.classList.toggle('hidden',!isIt);its.forEach(x=>x.required=isIt);if(!sales)sfi.value='';};update();role?.addEventListener('change',update);extra.addEventListener('change',update);});</script>
